p rows($scan['videos'],$existing,'video')?></div></details></form><section class="phone-preview"><div class="phone"><iframe id="preview" src="view.php?slug=<?=urlencode($slug)?>"></iframe></div><p>Preview setelah disimpan</p></section></div></main></body></html>
